function is_demo_tenant_v12(array $tenant):bool{return in_array((string)($tenant['slug']??''),['tienda-demo','restaurante-demo'],true);}

function module_enabled_v12(App $app,array $tenant,string $module):bool
{
    if(!isset(FISITAPP_MODULES_V12[$module]))return false;
    if(is_demo_tenant_v12($tenant)&&in_array($module,['express','drivers'],true))return false;
    if((int)FISITAPP_MODULES_V12[$module][2]===1)return true;
    try{
        $override=$app->one('SELECT enabled FROM tenant_modules WHERE tenant_id=? AND module_key=?',[$tenant['id'],$module]);
        if($override!==null)return (bool)$override['enabled'];
        $row=$app->one('SELECT pm.enabled FROM plans p JOIN plan_modules pm ON pm.plan_id=p.id WHERE p.name=? AND p.status="active" AND pm.module_key=? LIMIT 1',[$tenant['plan']?:'Profesional',$module]);
        return $row===null?true:(bool)$row['enabled'];
    }catch(Throwable){return true;}
}

function require_module_v12(App $app,array $tenant,string $module):void
{
    if(module_enabled_v12($app,$tenant,$module))return;
    http_response_code(403);simple_error('Módulo no incluido','Esta función no está habilitada en el plan actual de la tienda.');exit;
}

function section_module_v12(string $section):string
{
    if(function_exists('r2_alias')) $section=r2_alias($section);
    return match($section){
        'sucursales'=>'multibranch','opciones'=>'advanced_products','cupones'=>'promotions','clientes'=>'customers',
        'fidelizacion'=>'loyalty','express'=>'express','cocina','repartidor','pedidos','delivery'=>'operations',
        'reportes'=>'reports','usuarios'=>'team','auditoria'=>'team','contenido'=>'content','blog'=>'content','contactos'=>'content','ventas'=>'pos','cobro'=>'pos','express-pendientes'=>'pos','turnos'=>'shifts','inventario'=>'inventory','compras'=>'purchases','cxc'=>'receivables','cxp'=>'payables','impresion'=>'store',default=>'store'
    };
}

function master_modules_v12(App $app,array $user):void
{
    if(is_post()){
        verify_csrf();$action=(string)($_POST['action']??'plan');
        try{
            if($action==='tenant'){
                $tenantId=(int)$_POST['tenant_id'];$plan=trim((string)$_POST['plan']);
                if(!$app->one('SELECT id FROM plans WHERE name=? AND status="active"',[$plan]))throw new RuntimeException('El plan seleccionado no existe.');
                $app->exec("UPDATE tenants SET plan=? WHERE id=? AND slug NOT IN ('tienda-demo','restaurante-demo')",[$plan,$tenantId]);
                $app->exec('DELETE FROM tenant_modules WHERE tenant_id=?',[$tenantId]);audit($app,$tenantId,$user['id'],'assign_plan','tenant',$tenantId);
            }else{
                $planId=(int)$_POST['plan_id'];$plan=$app->one('SELECT * FROM plans WHERE id=?',[$planId]);if(!$plan)throw new RuntimeException('Plan no encontrado.');
                $enabled=array_fill_keys(array_map('strval',$_POST['modules']??[]),true);
                foreach(FISITAPP_MODULES_V12 as $key=>$meta)$app->exec('INSERT INTO plan_modules(plan_id,module_key,enabled) VALUES(?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled)',[$planId,$key,isset($enabled[$key])||$meta[2]?1:0]);
                $limits=['branches'=>max(1,(int)($_POST['limit_branches']??1)),'users'=>max(1,(int)($_POST['limit_users']??3)),'products'=>max(1,(int)($_POST['limit_products']??100)),'orders_month'=>max(1,(int)($_POST['limit_orders']??500))];
                $app->exec('UPDATE plans SET price=?,billing_period=?,limits_json=? WHERE id=?',[(float)($_POST['price']??0),in_array($_POST['billing_period']??'monthly',['monthly','annual','custom'],true)?$_POST['billing_period']:'monthly',json_encode($limits),$planId]);
            }
            flash('success','Configuración modular actualizada.');
        }catch(Throwable $e){flash('error',$e->getMessage());}
        redirect(url('master/modules'));
    }
    $plans=$app->all('SELECT * FROM plans ORDER BY sort_order,id');$tenants=$app->all("SELECT id,name,plan FROM tenants WHERE slug NOT IN ('tienda-demo','restaurante-demo') ORDER BY name");
    $matrix=[];foreach($app->all('SELECT * FROM plan_modules') as $row)$matrix[(int)$row['plan_id']][$row['module_key']]=(bool)$row['enabled'];
    admin_shell_start('Planes y módulos',$user,null,'modules');
    echo '<div class="grid grid-3">';foreach($plans as $plan){$limits=json_decode((string)$plan['limits_json'],true)?:[];echo '<form class="card admin-card" method="post">'.csrf_field().'<input type="hidden" name="action" value="plan"><input type="hidden" name="plan_id" value="'.(int)$plan['id'].'"><span class="tag">PLAN</span><h2>'.e($plan['name']).'</h2><div class="split">'.field('Precio','price',$plan['price'],true,'number','0.01').'<div class="form-group"><label>Periodicidad</label><select class="input" name="billing_period"><option value="monthly">Mensual</option><option value="annual" '.($plan['billing_period']==='annual'?'selected':'').'>Anual</option><option value="custom" '.($plan['billing_period']==='custom'?'selected':'').'>Personalizada</option></select></div></div><div class="module-checks">';foreach(FISITAPP_MODULES_V12 as $key=>$meta){$checked=$meta[2]||($matrix[(int)$plan['id']][$key]??false);echo '<label><input type="checkbox" name="modules[]" value="'.e($key).'" '.($checked?'checked':'').' '.($meta[2]?'disabled':'').'> <span><strong>'.e($meta[0]).'</strong><small>'.e($meta[1]).'</small></span></label>';}echo '</div><h3>Límites</h3><div class="split">'.field('Sucursales','limit_branches',$limits['branches']??1,true,'number','1').field('Usuarios','limit_users',$limits['users']??3,true,'number','1').field('Productos','limit_products',$limits['products']??100,true,'number','1').field('Pedidos/mes','limit_orders',$limits['orders_month']??500,true,'number','1').'</div><button class="btn btn-block">Guardar plan</button></form>';}echo '</div><section class="card admin-card" style="margin-top:20px"><h2>Asignar plan a una tienda</h2><form method="post">'.csrf_field().'<input type="hidden" name="action" value="tenant"><div class="split"><div class="form-group"><label>Tienda</label><select class="input" name="tenant_id">';foreach($tenants as $tenant)echo '<option value="'.(int)$tenant['id'].'">'.e($tenant['name']).' · '.e($tenant['plan']).'</option>';echo '</select></div><div class="form-group"><label>Plan</label><select class="input" name="plan">';foreach($plans as $plan)if($plan['status']==='active')echo '<option>'.e($plan['name']).'</option>';echo '</select></div></div><button class="btn">Aplicar plan y sus módulos</button></form></section>';admin_shell_end();
}

function tenant_loyalty_v12(App $app,array $user,array $tenant):void
{
    require_module_v12($app,$tenant,'loyalty');
    if(is_post()&&function_exists('r3_active')&&r3_active($app)&&($_POST['action']??'')==='gift_recharge')r3_gift_recharge($app,$user,$tenant);
    if(is_post()&&function_exists('r2_active')&&r2_active($app)&&($_POST['action']??'')==='gift_card')r2_gift_issue($app,$user,$tenant);
    if(is_post()){
        verify_csrf();try{
            $action=(string)($_POST['action']??'save_program');
            if($action==='redeem'){
                $code=strtoupper(trim((string)($_POST['reward_code']??'')));if(!preg_match('/^FIEL-[A-Z0-9]{10}$/',$code))throw new RuntimeException('El código del premio no es válido.');
                $app->db->beginTransaction();$reward=$app->one('SELECT lr.*,la.tenant_id,u.name customer_name,lp.name program_name,p.name product_name FROM loyalty_rewards lr JOIN loyalty_accounts la ON la.id=lr.account_id JOIN users u ON u.id=la.user_id JOIN loyalty_programs lp ON lp.id=lr.program_id LEFT JOIN products p ON p.id=lr.reward_product_id WHERE lr.code=? AND la.tenant_id=? FOR UPDATE',[$code,$tenant['id']]);
                if(!$reward)throw new RuntimeException('El premio no pertenece a esta tienda.');if($reward['status']!=='available')throw new RuntimeException('Este premio ya fue utilizado o no está disponible.');if(strtotime((string)$reward['expires_at'])<time()){$app->exec('UPDATE loyalty_rewards SET status="expired" WHERE id=?',[$reward['id']]);$app->db->commit();throw new RuntimeException('Este premio ya venció.');}
                $app->exec('UPDATE loyalty_rewards SET status="used" WHERE id=? AND status="available"',[$reward['id']]);$app->exec('UPDATE loyalty_accounts SET rewards_available=GREATEST(rewards_available-1,0) WHERE id=?',[$reward['account_id']]);$app->exec('INSERT INTO loyalty_ledger(account_id,event,description) VALUES(?,"redeem",?)',[$reward['account_id'],'Premio '.$code.' canjeado']);$app->db->commit();audit($app,$tenant['id'],$user['id'],'loyalty_redeem','loyalty_reward',(int)$reward['id']);flash('success','Premio canjeado para '.$reward['customer_name'].'.');redirect(url('admin/fidelizacion'));
            }
            $mode=in_array($_POST['mode']??'points',['points','purchases','spend'],true)?$_POST['mode']:'points';$reward=in_array($_POST['reward_type']??'percent',['percent','fixed','product'],true)?$_POST['reward_type']:'percent';$branchId=(int)($_POST['branch_id']??0)?:null;
            $values=[trim((string)($_POST['name']??'Programa de fidelización')),$mode,max(.01,(float)($_POST['earn_value']??1)),max(1,(float)($_POST['goal_value']??10)),$reward,max(0,(float)($_POST['reward_value']??0)),(int)($_POST['reward_product_id']??0)?:null,isset($_POST['is_active'])?1:0];$existing=$branchId?$app->one('SELECT id FROM loyalty_programs WHERE tenant_id=? AND branch_id=?',[$tenant['id'],$branchId]):$app->one('SELECT id FROM loyalty_programs WHERE tenant_id=? AND branch_id IS NULL ORDER BY id LIMIT 1',[$tenant['id']]);if($existing)$app->exec('UPDATE loyalty_programs SET name=?,mode=?,earn_value=?,goal_value=?,reward_type=?,reward_value=?,reward_product_id=?,is_active=? WHERE id=? AND tenant_id=?',array_merge($values,[$existing['id'],$tenant['id']]));else $app->exec('INSERT INTO loyalty_programs(tenant_id,branch_id,name,mode,earn_value,goal_value,reward_type,reward_value,reward_product_id,is_active) VALUES(?,?,?,?,?,?,?,?,?,?)',array_merge([$tenant['id'],$branchId],$values));
            audit($app,$tenant['id'],$user['id'],'loyalty_config','tenant',$tenant['id']);flash('success','Programa de fidelización actualizado.');
        }catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e->getMessage());}redirect(url('admin/fidelizacion'));
    }
    $app->exec('UPDATE loyalty_rewards lr JOIN loyalty_accounts la ON la.id=lr.account_id SET lr.status="expired" WHERE la.tenant_id=? AND lr.status="available" AND lr.expires_at<NOW()',[$tenant['id']]);
    $program=$app->one('SELECT * FROM loyalty_programs WHERE tenant_id=? AND branch_id IS NULL',[$tenant['id']])?:[];$branches=tenant_branches_v1($app,(int)$tenant['id'],false);$products=$app->all("SELECT id,name FROM products WHERE tenant_id=? AND status!='hidden' ORDER BY name",[$tenant['id']]);
    $accounts=$app->all('SELECT la.*,u.name,u.email,u.phone FROM loyalty_accounts la JOIN users u ON u.id=la.user_id WHERE la.tenant_id=? ORDER BY la.updated_at DESC LIMIT 200',[$tenant['id']]);
    $recentRewards=$app->all('SELECT lr.code,lr.status,lr.expires_at,lr.created_at,u.name customer_name,lr.reward_type,lr.reward_value,p.name product_name FROM loyalty_rewards lr JOIN loyalty_accounts la ON la.id=lr.account_id JOIN users u ON u.id=la.user_id JOIN loyalty_programs lp ON lp.id=lr.program_id LEFT JOIN products p ON p.id=lr.reward_product_id WHERE la.tenant_id=? ORDER BY lr.created_at DESC LIMIT 30',[$tenant['id']]);
    admin_shell_start('Fidelización',$user,$tenant,'fidelizacion');if(function_exists('r2_active')&&r2_active($app))r2_gift_form($app,$tenant);echo '<div class="split"><form class="card admin-card" method="post">'.csrf_field().'<input type="hidden" name="action" value="save_program"><h2>Programa global</h2>'.field('Nombre','name',$program['name']??'Clientes frecuentes',true).'<div class="form-group"><label>Modo</label><select class="input" name="mode"><option value="points">Puntos por monto comprado</option><option value="purchases" '.(($program['mode']??'')==='purchases'?'selected':'').'>Cantidad de compras</option><option value="spend" '.(($program['mode']??'')==='spend'?'selected':'').'>Monto acumulado</option></select></div><div class="split">'.field('Valor de acumulación','earn_value',$program['earn_value']??100,true,'number','0.01').field('Meta para premio','goal_value',$program['goal_value']??10,true,'number','0.01').'</div><div class="form-group"><label>Premio</label><select class="input" name="reward_type"><option value="percent">Descuento porcentual</option><option value="fixed" '.(($program['reward_type']??'')==='fixed'?'selected':'').'>Tarjeta de regalo / descuento fijo (un uso)</option><option value="product" '.(($program['reward_type']??'')==='product'?'selected':'').'>Producto gratis</option></select></div>'.field('Valor del premio','reward_value',$program['reward_value']??10,true,'number','0.01').'<div class="form-group"><label>Producto de premio</label><select class="input" name="reward_product_id"><option value="">No aplica</option>';foreach($products as $product)echo '<option value="'.(int)$product['id'].'" '.(($program['reward_product_id']??0)==$product['id']?'selected':'').'>'.e($product['name']).'</option>';echo '</select></div><label><input type="checkbox" name="is_active" '.(($program['is_active']??0)?'checked':'').'> Programa activo</label><button class="btn btn-block" style="margin-top:14px">Guardar programa</button></form><section class="card admin-card"><h2>Canjear premio</h2><p class="muted">Escanea el QR de la tarjeta del cliente o escribe su código. Cada premio solo puede canjearse una vez.</p><form method="post" class="loyalty-redeem-form">'.csrf_field().'<input type="hidden" name="action" value="redeem"><div class="form-group"><label>Código del premio</label><input class="input" name="reward_code" data-reward-code required maxlength="15" placeholder="FIEL-XXXXXXXXXX" autocomplete="off"></div><button class="btn btn-block" type="submit">Validar y canjear</button></form><button class="btn btn-light btn-block" type="button" data-qr-scan-open>Escanear código QR</button><div class="qr-scanner" data-qr-scanner hidden><video playsinline muted></video><p class="muted" data-qr-scan-status>Apunta la cámara al QR del premio.</p><button class="btn btn-light" type="button" data-qr-scan-close>Cerrar cámara</button></div><hr><h3>Cómo se acredita</h3><p class="muted">Solo suma cuando el pedido queda entregado. Los pedidos cancelados no suman.</p></section></div><section class="card admin-card" style="margin-top:20px"><h2>Progreso de clientes</h2><div class="table-wrap"><table class="table"><tr><th>Cliente</th><th>Puntos</th><th>Compras</th><th>Monto</th><th>Premios</th></tr>';foreach($accounts as $row)echo '<tr><td>'.e($row['name']).'<br><small>'.e($row['email']).'</small></td><td>'.e($row['points_balance']).'</td><td>'.e($row['purchases_balance']).'</td><td>'.money((float)$row['spend_balance']).'</td><td>'.e($row['rewards_available']).'</td></tr>';if(!$accounts)echo '<tr><td colspan="5">Todavía no hay movimientos.</td></tr>';echo '</table></div></section><section class="card admin-card" style="margin-top:20px"><h2>Premios recientes</h2><div class="table-wrap"><table class="table"><tr><th>Código</th><th>Cliente</th><th>Premio</th><th>Estado</th><th>Vence</th></tr>';foreach($recentRewards as $item){$description=$item['reward_type']==='percent'?((float)$item['reward_value']).'% de descuento':($item['reward_type']==='fixed'?money((float)$item['reward_value']):($item['product_name']?:'Producto gratis'));echo '<tr><td><code>'.e($item['code']).'</code></td><td>'.e($item['customer_name']).'</td><td>'.e($description).'</td><td><span class="status '.($item['status']!=='available'?'status-off':'').'">'.e($item['status']).'</span></td><td>'.e(date('d/m/Y',strtotime($item['expires_at']))).'</td></tr>';}if(!$recentRewards)echo '<tr><td colspan="5">Todavía no hay premios.</td></tr>';echo '</table></div></section>';admin_shell_end();
}

function loyalty_sync_order_v12(App $app,int $orderId):void
{
    $order=$app->one('SELECT * FROM orders WHERE id=?',[$orderId]);if(!$order||$order['status']!=='delivered'||empty($order['user_id']))return;$tenant=$app->one('SELECT * FROM tenants WHERE id=?',[$order['tenant_id']]);if(!$tenant||!module_enabled_v12($app,$tenant,'loyalty'))return;
    $program=$app->one('SELECT * FROM loyalty_programs WHERE tenant_id=? AND is_active=1 AND (branch_id=? OR branch_id IS NULL) ORDER BY branch_id DESC LIMIT 1',[$order['tenant_id'],$order['branch_id']]);if(!$program)return;
    $ownsTransaction=!$app->db->inTransaction();if($ownsTransaction)$app->db->beginTransaction();try{
        if($app->one('SELECT id FROM loyalty_ledger WHERE order_id=? AND event="earn" FOR UPDATE',[$orderId])){if($ownsTransaction)$app->db->commit();return;}
        $app->exec('INSERT INTO loyalty_accounts(tenant_id,user_id) VALUES(?,?) ON DUPLICATE KEY UPDATE updated_at=NOW()',[$order['tenant_id'],$order['user_id']]);$account=$app->one('SELECT * FROM loyalty_accounts WHERE tenant_id=? AND user_id=? FOR UPDATE',[$order['tenant_id'],$order['user_id']]);
        $points=$program['mode']==='points'?floor((float)$order['total']/max(.01,(float)$program['earn_value'])):0;$purchases=$program['mode']==='purchases'?1:0;$spend=$program['mode']==='spend'?(float)$order['total']:0;
        $app->exec('UPDATE loyalty_accounts SET points_balance=points_balance+?,purchases_balance=purchases_balance+?,spend_balance=spend_balance+? WHERE id=?',[$points,$purchases,$spend,$account['id']]);$app->exec('INSERT INTO loyalty_ledger(account_id,order_id,event,points_delta,purchases_delta,spend_delta,description) VALUES(?,? ,"earn",?,?,?,?)',[$account['id'],$orderId,$points,$purchases,$spend,'Pedido #'.$order['order_number'].' entregado']);
        $updated=$app->one('SELECT * FROM loyalty_accounts WHERE id=?',[$account['id']]);$balance=$program['mode']==='points'?(float)$updated['points_balance']:($program['mode']==='purchases'?(float)$updated['purchases_balance']:(float)$updated['spend_balance']);$goal=max(1,(float)$program['goal_value']);
        if($balance>=$goal){$code='FIEL-'.strtoupper(substr(bin2hex(random_bytes(5)),0,10));$app->exec('INSERT INTO loyalty_rewards(account_id,program_id,code,reward_type,reward_value,reward_product_id,status,expires_at) VALUES(?,?,?,?,?,?,"available",DATE_ADD(NOW(),INTERVAL 90 DAY))',[$account['id'],$program['id'],$code,$program['reward_type'],$program['reward_value'],$program['reward_product_id']]);$field=$program['mode']==='points'?'points_balance':($program['mode']==='purchases'?'purchases_balance':'spend_balance');$app->exec("UPDATE loyalty_accounts SET $field=$field-?,rewards_available=rewards_available+1 WHERE id=?",[$goal,$account['id']]);}
        if($ownsTransaction)$app->db->commit();
    }catch(Throwable $e){if($ownsTransaction&&$app->db->inTransaction())$app->db->rollBack();throw $e;}
}

function loyalty_checkout_reward_v12(App $app,int $tenantId,int $userId,string $code,float $subtotal,array $lines):array
{
    $tenant=$app->one('SELECT * FROM tenants WHERE id=?',[$tenantId]);if(!$tenant||!module_enabled_v12($app,$tenant,'loyalty'))throw new DomainException('La fidelización no está activa en esta tienda.');
    $reward=$app->one('SELECT lr.*,la.tenant_id,la.user_id,p.name product_name FROM loyalty_rewards lr JOIN loyalty_accounts la ON la.id=lr.account_id LEFT JOIN products p ON p.id=lr.reward_product_id WHERE lr.code=? AND la.tenant_id=? AND la.user_id=? FOR UPDATE',[$code,$tenantId,$userId]);
    if(!$reward||$reward['status']!=='available')throw new DomainException('El premio no es válido o ya fue utilizado.');if(strtotime((string)$reward['expires_at'])<time()){$app->exec('UPDATE loyalty_rewards SET status="expired" WHERE id=?',[$reward['id']]);throw new DomainException('Este premio ya venció.');}
    if($reward['reward_type']==='percent')$discount=min($subtotal,$subtotal*((float)$reward['reward_value']/100));elseif($reward['reward_type']==='fixed')$discount=min($subtotal,(float)$reward['reward_value']);else{$discount=0.0;foreach($lines as $line)if((int)$line['product']['id']===(int)$reward['reward_product_id']){$discount=min($subtotal,(float)$line['price']);break;}if($discount<=0)throw new DomainException('Agrega '.($reward['product_name']?:'el producto del premio').' al carrito para canjearlo gratis.');}
    return [$reward,$discount];
}

function loyalty_consume_checkout_reward_v12(App $app,array $reward,int $orderId):void
{
    $app->exec('UPDATE loyalty_rewards SET status="used",used_order_id=? WHERE id=? AND status="available"',[$orderId,$reward['id']]);$app->exec('UPDATE loyalty_accounts SET rewards_available=GREATEST(rewards_available-1,0) WHERE id=?',[$reward['account_id']]);$app->exec('INSERT INTO loyalty_ledger(account_id,order_id,event,description) VALUES(?,?,"redeem",?)',[$reward['account_id'],$orderId,'Premio '.$reward['code'].' aplicado al pedido']);
}

function loyalty_customer_cards_v12(App $app,int $userId):string
{
    $giftHtml=function_exists('r3_active')&&r3_active($app)?r3_gift_customer($app,$userId):'';
    $intro=$giftHtml.'<section id="fidelizacion" class="loyalty-customer"><div class="section-head loyalty-head"><div><span class="tag">BENEFICIOS</span><h2>Mi fidelización</h2><p class="muted">Tus avances se acreditan cuando cada pedido queda entregado.</p></div></div>';
    try{
        $rows=$app->all('SELECT COALESCE(la.id,0) id,t.id tenant_id,t.name tenant_name,t.logo,t.primary_color,t.accent_color,t.plan,lp.name program_name,lp.mode,lp.goal_value,COALESCE(la.points_balance,0) points_balance,COALESCE(la.purchases_balance,0) purchases_balance,COALESCE(la.spend_balance,0) spend_balance,COALESCE(la.rewards_available,0) rewards_available,COALESCE(la.updated_at,lp.updated_at) updated_at FROM (SELECT DISTINCT tenant_id FROM orders WHERE user_id=? UNION SELECT tenant_id FROM loyalty_accounts WHERE user_id='.(int)$userId.') customer_tenants JOIN tenants t ON t.id=customer_tenants.tenant_id AND t.is_active=1 JOIN loyalty_programs lp ON lp.id=(SELECT lp2.id FROM loyalty_programs lp2 WHERE lp2.tenant_id=t.id AND lp2.is_active=1 ORDER BY (lp2.branch_id IS NULL) DESC,lp2.id LIMIT 1) LEFT JOIN loyalty_accounts la ON la.tenant_id=t.id AND la.user_id=? ORDER BY updated_at DESC',[$userId,$userId]);
        $rows=array_values(array_filter($rows,static fn(array $row):bool=>module_enabled_v12($app,['id'=>$row['tenant_id'],'plan'=>$row['plan']],'loyalty')));
        $rewards=$app->all('SELECT lr.*,t.name tenant_name,lp.name program_name,p.name product_name FROM loyalty_rewards lr JOIN loyalty_accounts la ON la.id=lr.account_id JOIN tenants t ON t.id=la.tenant_id JOIN loyalty_programs lp ON lp.id=lr.program_id LEFT JOIN products p ON p.id=lr.reward_product_id WHERE la.user_id=? AND lr.status="available" AND lr.expires_at>NOW() ORDER BY lr.created_at DESC',[$userId]);
        $history=$app->all('SELECT ll.*,t.name tenant_name,lp.mode FROM loyalty_ledger ll JOIN loyalty_accounts la ON la.id=ll.account_id JOIN tenants t ON t.id=la.tenant_id LEFT JOIN loyalty_programs lp ON lp.id=(SELECT lp2.id FROM loyalty_programs lp2 WHERE lp2.tenant_id=la.tenant_id AND lp2.is_active=1 ORDER BY (lp2.branch_id IS NULL) DESC,lp2.id LIMIT 1) WHERE la.user_id=? ORDER BY ll.created_at DESC LIMIT 30',[$userId]);
    }catch(Throwable){return $intro.'<div class="loyalty-empty"><h3>Tu tarjeta digital aparecerá aquí</h3><p class="muted">Cuando compres en una tienda con fidelización activa podrás consultar en este panel tus puntos, compras, premios y movimientos.</p></div></section>';}
    if(!$rows&&!$rewards)return $intro.'<div class="loyalty-empty"><h3>Aún no tienes avances</h3><p class="muted">Cuando compres en una tienda con fidelización activa y el pedido sea entregado, aquí verás tu tarjeta digital y el progreso hacia tu próximo premio.</p></div></section>';
    $html=$intro.'<div class="loyalty-wallet">';foreach($rows as $row){if(!$row['mode'])continue;$value=(float)($row['mode']==='points'?$row['points_balance']:($row['mode']==='purchases'?$row['purchases_balance']:$row['spend_balance']));$goal=max(1,(float)$row['goal_value']);$percent=min(100,max(0,($value/$goal)*100));$modeLabel=$row['mode']==='points'?'puntos':($row['mode']==='purchases'?'compras':'acumulado');$valueLabel=$row['mode']==='spend'?money($value):(fmod($value,1.0)===0.0?(string)(int)$value:(string)$value);$goalLabel=$row['mode']==='spend'?money($goal):(string)(int)$goal;$primary=preg_match('/^#[0-9a-f]{6}$/i',(string)$row['primary_color'])?$row['primary_color']:'#123d2c';$accent=preg_match('/^#[0-9a-f]{6}$/i',(string)$row['accent_color'])?$row['accent_color']:'#dff1cb';$member='FIS-'.str_pad((string)$row['tenant_id'],4,'0',STR_PAD_LEFT).'-'.str_pad((string)$userId,6,'0',STR_PAD_LEFT);$progressVisual='<div class="loyalty-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'.(int)$percent.'"><i style="width:'.round($percent,2).'%"></i></div>';if($row['mode']==='purchases'&&$goal<=12){$progressVisual='<div class="loyalty-stamps" role="img" aria-label="'.(int)$value.' de '.(int)$goal.' compras">';for($stamp=1;$stamp<=(int)$goal;$stamp++)$progressVisual.='<i class="'.($stamp<=$value?'done':'').'">'.($stamp<=$value?'✓':$stamp).'</i>';$progressVisual.='</div>';}$html.='<article class="loyalty-digital-card" style="--card-primary:'.e($primary).';--card-accent:'.e($accent).'"><header>'.($row['logo']?'<img src="'.e(public_media_url($row['logo'])).'" alt="">':'<span class="loyalty-brand-mark">F</span>').'<div><strong>'.e($row['tenant_name']).'</strong><small>'.e($row['program_name']??'Clientes frecuentes').'</small></div></header><div class="loyalty-card-main"><span>Tu progreso</span><strong>'.$valueLabel.' <small>'.e($modeLabel).'</small></strong>'.$progressVisual.'<p>Te faltan <b>'.($row['mode']==='spend'?money(max(0,$goal-$value)):e((string)max(0,$goal-$value))).'</b> para tu próximo premio.</p></div><footer><span>Meta: '.$goalLabel.'</span><code>'.e($member).'</code></footer></article>';}$html.='</div>';
    if($rewards){$html.='<div class="loyalty-rewards"><h3>Premios disponibles</h3><div class="grid grid-3">';foreach($rewards as $reward){$description=$reward['reward_type']==='percent'?((float)$reward['reward_value']).'% de descuento':($reward['reward_type']==='fixed'?money((float)$reward['reward_value']):($reward['product_name']?:'Producto gratis'));$html.='<article class="loyalty-reward-ticket"><span class="tag">PREMIO DISPONIBLE</span><strong>'.e($description).'</strong><small>'.e($reward['tenant_name']).' · '.e($reward['program_name']).'</small><div class="loyalty-qr" data-loyalty-qr="'.e($reward['code']).'" aria-label="Código QR del premio"></div><code>'.e($reward['code']).'</code><small>Vence '.e(date('d/m/Y',strtotime($reward['expires_at']))).'</small><p>Muéstralo en la tienda para canjearlo.</p></article>';}$html.='</div></div>';}
    if($history){$html.='<details class="card loyalty-history"><summary>Ver historial de fidelización</summary><div class="loyalty-history-list">';foreach($history as $item){$delta=$item['mode']==='points'?(float)$item['points_delta']:($item['mode']==='purchases'?(float)$item['purchases_delta']:(float)$item['spend_delta']);$deltaLabel=$item['event']==='redeem'?'Canje realizado':($item['mode']==='spend'?money($delta):(($delta>=0?'+':'').(fmod($delta,1.0)===0.0?(string)(int)$delta:(string)$delta)));$html.='<article><div><strong>'.e($item['tenant_name']).'</strong><small>'.e($item['description']??'Movimiento de fidelización').'</small></div><div><b>'.e($deltaLabel).'</b><small>'.e(date('d/m/Y H:i',strtotime($item['created_at']))).'</small></div></article>';}$html.='</div></details>';}$html.='</section>';return $html;
}

function express_publish_qa(App $app,array $tenant,int $orderId):string
{
    $app->db->beginTransaction();
    $order=$app->one('SELECT o.*,z.name zone_name FROM orders o LEFT JOIN delivery_zones z ON z.id=o.delivery_zone_id WHERE o.id=? AND o.tenant_id=? AND o.delivery_type IN ("delivery","coordinated") FOR UPDATE',[$orderId,$tenant['id']]);
    if(!$order||!in_array($order['status'],['confirmed','preparing','ready'],true))throw new RuntimeException('Confirma el pedido antes de publicarlo. No se pueden publicar pedidos cancelados o entregados.');
    $previous=$app->one('SELECT status FROM delivery_jobs WHERE order_id=? FOR UPDATE',[$orderId]);
    if($previous&&!in_array($previous['status'],['cancelled','expired'],true))throw new RuntimeException('Este express ya está publicado. Usa Renovar PIN si perdiste el código.');
    $payout=(float)($_POST['payout']??$order['delivery_total']);if(!is_finite($payout)||$payout<0)throw new RuntimeException('El pago al motorizado debe ser un monto válido.');
    $pin=(string)random_int(1000,9999);
    $app->exec('INSERT INTO delivery_jobs(tenant_id,branch_id,order_id,status,payout,zone_label,pickup_ready_at,delivery_pin_hash) VALUES(?,?,?,"available",?,?,NOW(),?) ON DUPLICATE KEY UPDATE status="available",assigned_driver_id=NULL,accepted_at=NULL,picked_up_at=NULL,delivered_at=NULL,issue_previous_status=NULL,payout=VALUES(payout),zone_label=VALUES(zone_label),pickup_ready_at=NOW(),delivery_pin_hash=VALUES(delivery_pin_hash)',[$tenant['id'],$order['branch_id'],$orderId,$payout,$order['zone_name']?:'Zona coordinada',password_hash($pin,PASSWORD_DEFAULT)]);
    $app->db->commit();return $pin;
}

function express_job_action_qa(App $app,array $tenant,string $action,int $jobId):void
{
    $app->db->beginTransaction();
    $job=$app->one('SELECT j.*,o.status order_status FROM delivery_jobs j JOIN orders o ON o.id=j.order_id WHERE j.id=? AND j.tenant_id=? FOR UPDATE',[$jobId,$tenant['id']]);
    if(!$job||in_array($job['status'],['delivered','cancelled','expired'],true)||in_array($job['order_status'],['cancelled','delivered'],true))throw new RuntimeException('Esta entrega ya terminó o no está disponible para este negocio.');
    if($action==='renew_pin'){
        $pin=(string)random_int(1000,9999);$app->exec('UPDATE delivery_jobs SET delivery_pin_hash=?,updated_at=NOW() WHERE id=?',[password_hash($pin,PASSWORD_DEFAULT),$jobId]);
        $app->db->commit();flash('success','PIN de entrega: '.$pin.'. Compártelo con el cliente; el PIN anterior dejó de funcionar.');return;
    }
    if($job['status']!=='issue')throw new RuntimeException('Solo se puede resolver una entrega con incidencia.');
    $resume=(string)($job['issue_previous_status']??'');if(!in_array($resume,['assigned','arrived','picked_up','in_transit'],true))$resume=$job['picked_up_at']?'in_transit':'assigned';
    $app->exec('UPDATE delivery_jobs SET status=?,issue_previous_status=NULL,updated_at=NOW() WHERE id=?',[$resume,$jobId]);$app->db->commit();
    flash('success','Incidencia resuelta. El mismo motorizado puede continuar desde el paso anterior.');
}

function express_assign_qa(App $app,array $tenant,int $driverId,int $jobId):void
{
    if(!module_enabled_v12($app,$tenant,'drivers'))throw new RuntimeException('La red de motorizados no está activa en este negocio.');
    $app->db->beginTransaction();
    $driver=$app->one('SELECT p.user_id FROM driver_profiles p JOIN users u ON u.id=p.user_id AND u.role="driver" AND u.is_active=1 WHERE p.user_id=? FOR UPDATE',[$driverId]);
    if(!$driver)throw new RuntimeException('Motorizado no disponible.');
    if($app->one('SELECT id FROM delivery_jobs WHERE assigned_driver_id=? AND status IN ("assigned","arrived","picked_up","in_transit","issue") LIMIT 1 FOR UPDATE',[$driverId]))throw new RuntimeException('Este motorizado tiene una entrega activa. Espera a que termine o elige otro.');
    $job=$app->one('SELECT j.id FROM delivery_jobs j JOIN orders o ON o.id=j.order_id AND o.status NOT IN ("cancelled","delivered") JOIN driver_affiliations da ON da.tenant_id=j.tenant_id AND da.user_id=? AND da.status="active" WHERE j.id=? AND j.tenant_id=? AND j.status="available" AND (da.all_branches=1 OR EXISTS(SELECT 1 FROM driver_affiliation_branches dab WHERE dab.affiliation_id=da.id AND dab.branch_id=j.branch_id)) FOR UPDATE',[$driverId,$jobId,$tenant['id']]);
    if(!$job)throw new RuntimeException('El express no está disponible o el motorizado no puede atender esta sucursal.');
    $app->exec('UPDATE delivery_jobs SET assigned_driver_id=?,status="assigned",accepted_at=NOW(),updated_at=NOW() WHERE id=?',[$driverId,$jobId]);$app->db->commit();
    flash('success','Entrega asignada al motorizado.');
}

function tenant_express_v12(App $app,array $user,array $tenant):void
{
    require_module_v12($app,$tenant,'express');
    if(is_post()){
        verify_csrf();try{$action=(string)($_POST['action']??'publish');$orderId=(int)($_POST['order_id']??0);
            if($action==='publish'){$pin=express_publish_qa($app,$tenant,$orderId);flash('success','Express publicado. PIN de entrega: '.$pin.'. Compártelo con el cliente para confirmar la entrega.');}
            elseif(in_array($action,['renew_pin','resolve_issue'],true))express_job_action_qa($app,$tenant,$action,(int)($_POST['job_id']??0));
            elseif($action==='invite'){$email=strtolower(trim((string)($_POST['driver_email']??'')));$driver=$app->one('SELECT id,name FROM users WHERE email=? AND role="driver" AND is_active=1',[$email]);if(!$driver)throw new RuntimeException('No existe un motorizado activo con ese correo. Debe registrarse primero en FISITAPP Express.');$app->exec('INSERT INTO driver_affiliations(user_id,tenant_id,status,requested_by,all_branches,invited_by) VALUES(?,?,"pending_driver","tenant",1,?) ON DUPLICATE KEY UPDATE status=IF(status IN("active","blocked"),status,"pending_driver"),requested_by="tenant",invited_by=VALUES(invited_by)',[$driver['id'],$tenant['id'],$user['id']]);flash('success','Invitación enviada a '.$driver['name'].'.');}
            elseif($action==='affiliation_status'){$affiliationId=(int)($_POST['affiliation_id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['active','paused','rejected','blocked'],true))throw new RuntimeException('Estado de afiliación inválido.');$affiliation=$app->one('SELECT status FROM driver_affiliations WHERE id=? AND tenant_id=?',[$affiliationId,$tenant['id']]);if(!$affiliation)throw new RuntimeException('Afiliación no disponible.');if($status==='active'&&$affiliation['status']==='pending_driver')throw new RuntimeException('El motorizado debe aceptar primero su invitación.');$app->exec('UPDATE driver_affiliations SET status=? WHERE id=? AND tenant_id=?',[$status,$affiliationId,$tenant['id']]);flash('success','Afiliación actualizada.');}
            elseif($action==='affiliation_scope'){$affiliationId=(int)($_POST['affiliation_id']??0);$affiliation=$app->one('SELECT id FROM driver_affiliations WHERE id=? AND tenant_id=?',[$affiliationId,$tenant['id']]);if(!$affiliation)throw new RuntimeException('Afiliación no encontrada.');$allBranches=isset($_POST['all_branches'])?1:0;$app->db->beginTransaction();$app->exec('UPDATE driver_affiliations SET all_branches=? WHERE id=?',[$allBranches,$affiliationId]);$app->exec('DELETE FROM driver_affiliation_branches WHERE affiliation_id=?',[$affiliationId]);if(!$allBranches){foreach(array_unique(array_map('intval',$_POST['branches']??[])) as $branchId)if($app->one('SELECT id FROM branches WHERE id=? AND tenant_id=? AND is_active=1',[$branchId,$tenant['id']]))$app->exec('INSERT IGNORE INTO driver_affiliation_branches(affiliation_id,branch_id) VALUES(?,?)',[$affiliationId,$branchId]);}$app->db->commit();flash('success','Sucursales autorizadas actualizadas.');}
            elseif($action==='cancel')$app->exec('UPDATE delivery_jobs SET status="cancelled" WHERE id=? AND tenant_id=? AND status IN("available","assigned")',[(int)$_POST['job_id'],$tenant['id']]);
            elseif($action==='assign')express_assign_qa($app,$tenant,(int)($_POST['driver_id']??0),(int)($_POST['job_id']??0));
            audit($app,$tenant['id'],$user['id'],'express_'.$action,'delivery_job',(int)($_POST['job_id']??0));
        }catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e->getMessage());}redirect(url('admin/express'));
    }
    $ready=$app->all("SELECT o.id,o.order_number,o.customer_name,o.address,o.delivery_total,b.name branch_name FROM orders o LEFT JOIN branches b ON b.id=o.branch_id LEFT JOIN delivery_jobs j ON j.order_id=o.id WHERE o.tenant_id=? AND o.delivery_type IN ('delivery','coordinated') AND o.status IN ('confirmed','preparing','ready') AND j.id IS NULL ORDER BY o.created_at",[$tenant['id']]);
    $branches=$app->all('SELECT id,name FROM branches WHERE tenant_id=? AND is_active=1 ORDER BY is_default DESC,name',[$tenant['id']]);
    $drivers=$app->all('SELECT da.*,u.name,u.email,u.phone,dp.vehicle_type,dp.plate,dp.is_online,dp.rating,(SELECT GROUP_CONCAT(b.name ORDER BY b.name SEPARATOR ", ") FROM driver_affiliation_branches dab JOIN branches b ON b.id=dab.branch_id WHERE dab.affiliation_id=da.id) branch_names,(SELECT GROUP_CONCAT(dab.branch_id ORDER BY dab.branch_id SEPARATOR ",") FROM driver_affiliation_branches dab WHERE dab.affiliation_id=da.id) branch_ids FROM driver_affiliations da JOIN users u ON u.id=da.user_id AND u.role="driver" AND u.is_active=1 JOIN driver_profiles dp ON dp.user_id=u.id WHERE da.tenant_id=? ORDER BY FIELD(da.status,"pending_store","pending_driver","active","paused","rejected","blocked"),dp.is_online DESC,u.name',[$tenant['id']]);
    $jobs=$app->all('SELECT j.*,o.order_number,o.customer_name,o.address,b.name branch_name,u.name driver_name FROM delivery_jobs j JOIN orders o ON o.id=j.order_id LEFT JOIN branches b ON b.id=j.branch_id LEFT JOIN users u ON u.id=j.assigned_driver_id WHERE j.tenant_id=? ORDER BY FIELD(j.status,"available","assigned","arrived","picked_up","in_transit","issue","delivered","cancelled"),j.created_at DESC LIMIT 200',[$tenant['id']]);
    admin_shell_start('FISITAPP Express',$user,$tenant,'express');echo '<div class="split"><section class="card admin-card"><h2>Pedidos listos para publicar</h2>';foreach($ready as $order)echo '<form class="express-order" method="post">'.csrf_field().'<input type="hidden" name="action" value="publish"><input type="hidden" name="order_id" value="'.(int)$order['id'].'"><div><strong>#'.e($order['order_number']).' · '.e($order['customer_name']).'</strong><small>'.e($order['branch_name']??'Principal').' · '.e($order['address']).'</small></div><input class="input compact" type="number" name="payout" min="0" step="100" value="'.e($order['delivery_total']).'" aria-label="Pago"><button class="btn">Publicar express</button></form>';if(!$ready)echo '<p class="muted">No hay pedidos pendientes de publicación.</p>';echo '</section><section class="card admin-card"><span class="tag">RED MULTINEGOCIO</span><h2>Invitar motorizado</h2><p class="muted">El motorizado conserva una sola cuenta y debe aceptar la invitación.</p><form method="post">'.csrf_field().'<input type="hidden" name="action" value="invite">'.field('Correo registrado','driver_email','',true,'email').'<button class="btn btn-block">Enviar invitación</button></form><small class="muted">Registro para motorizados: '.e(url('driver-register')).'</small></section></div>';
    echo '<section class="card admin-card express-affiliations"><h2>Motorizados y solicitudes</h2>';foreach($drivers as $driver){$selectedBranches=array_filter(array_map('intval',explode(',',(string)($driver['branch_ids']??''))));echo '<article class="affiliation-row"><div><span class="driver-dot '.($driver['is_online']?'online':'').'"></span><strong>'.e($driver['name']).'</strong><small>'.e($driver['email']).' · '.e($driver['vehicle_type']).($driver['plate']?' · '.e($driver['plate']):'').' · '.e($driver['status']).'</small></div><form method="post" class="affiliation-scope">'.csrf_field().'<input type="hidden" name="action" value="affiliation_scope"><input type="hidden" name="affiliation_id" value="'.(int)$driver['id'].'"><label><input type="checkbox" name="all_branches" '.($driver['all_branches']?'checked':'').'> Todas las sucursales</label><div class="affiliation-branches">';foreach($branches as $branch){$selected=$driver['all_branches']||in_array((int)$branch['id'],$selectedBranches,true);echo '<label><input type="checkbox" name="branches[]" value="'.(int)$branch['id'].'" '.($selected?'checked':'').'> '.e($branch['name']).'</label>';}$scope=$driver['all_branches']?'Todas las sucursales':($driver['branch_names']?:'Sin sucursales');echo '</div><small>'.e($scope).'</small><button class="btn btn-light">Guardar alcance</button></form><form method="post" class="driver-actions">'.csrf_field().'<input type="hidden" name="action" value="affiliation_status"><input type="hidden" name="affiliation_id" value="'.(int)$driver['id'].'">'.($driver['status']==='pending_driver'?'<span class="status">Esperando aceptación</span>':($driver['status']!=='active'?'<button class="btn btn-accent" name="status" value="active">Aprobar/activar</button>':'<button class="btn btn-light" name="status" value="paused">Pausar</button>')).'<button class="btn btn-danger" name="status" value="blocked">Bloquear</button></form></article>';}if(!$drivers)echo '<div class="empty">Todavía no hay solicitudes ni motorizados afiliados.</div>';echo '</section>';
    echo '<section class="card admin-card" style="margin-top:20px"><h2>Express publicados</h2><div class="table-wrap"><table class="table"><tr><th>Pedido</th><th>Sucursal</th><th>Destino</th><th>Pago</th><th>Motorizado</th><th>Estado</th><th></th></tr>';foreach($jobs as $job)echo '<tr><td>#'.e($job['order_number']).'</td><td>'.e($job['branch_name']??'Principal').'</td><td>'.e($job['zone_label']).'</td><td>'.money((float)$job['payout']).'</td><td>'.e($job['driver_name']??'Disponible').'</td><td><span class="status">'.e(ui_label_qa((string)$job['status'])).'</span></td><td>'.(in_array($job['status'],['available','assigned'],true)?'<form method="post">'.csrf_field().'<input type="hidden" name="action" value="cancel"><input type="hidden" name="job_id" value="'.(int)$job['id'].'"><button class="btn btn-danger">Cancelar</button></form>':'').($job['status']==='issue'?'<form method="post">'.csrf_field().'<input type="hidden" name="action" value="resolve_issue"><input type="hidden" name="job_id" value="'.(int)$job['id'].'"><button class="btn btn-accent">Resolver y continuar</button></form>':'').(!in_array($job['status'],['delivered','cancelled','expired'],true)?'<form method="post">'.csrf_field().'<input type="hidden" name="action" value="renew_pin"><input type="hidden" name="job_id" value="'.(int)$job['id'].'"><button class="btn btn-light">Renovar PIN</button></form>':'').'</td></tr>';if(!$jobs)echo '<tr><td colspan="7">Todavía no se publicaron express.</td></tr>';echo '</table></div></section>';admin_shell_end();
}

function driver_register_page_v12(App $app):void
{
    if(current_user())redirect(role_home_url_v1($app,current_user()));
    if(is_post()){
        verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));try{if(!rate_limit_persistent($app,'driver-register',client_identity($email),5,900))throw new RuntimeException('Demasiados intentos. Espera unos minutos.');$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));$password=(string)($_POST['password']??'');$vehicle=in_array($_POST['vehicle_type']??'',['motorcycle','car','bicycle','other'],true)?$_POST['vehicle_type']:'motorcycle';if($name===''||$phone===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12)throw new RuntimeException('Completa los datos y usa una contraseña de al menos 12 caracteres.');if($app->one('SELECT id FROM users WHERE email=?',[$email]))throw new RuntimeException('Este correo ya está registrado.');$app->db->beginTransaction();$app->exec('INSERT INTO users(tenant_id,name,email,phone,password_hash,role,is_active,email_verified_at) VALUES(NULL,?,?,?,?,"driver",1,NOW())',[$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);$driverId=(int)$app->db->lastInsertId();$app->exec('INSERT INTO driver_profiles(user_id,vehicle_type,plate,identity_number,service_area,sinpe_phone,is_online) VALUES(?,?,?,?,?,?,0)',[$driverId,$vehicle,trim((string)($_POST['plate']??'')),trim((string)($_POST['identity_number']??'')),trim((string)($_POST['service_area']??'')),trim((string)($_POST['sinpe_phone']??$phone))]);$app->db->commit();flash('success','Perfil de motorizado creado. Ya puedes ingresar desde Acceso negocios.');redirect(url('owner-login'));}catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e->getMessage());}}
