function driver_portal_v12(App $app):void
{
    $user=require_login(['driver']);
    $app->exec('INSERT IGNORE INTO driver_profiles(user_id,vehicle_type,is_online) VALUES(? ,"motorcycle",0)',[$user['id']]);
    if(is_post()){
        verify_csrf();$action=(string)($_POST['action']??'toggle');try{
            if($action==='toggle')$app->exec('UPDATE driver_profiles SET is_online=? WHERE user_id=?',[isset($_POST['online'])?1:0,$user['id']]);
            elseif($action==='profile'){$vehicle=in_array($_POST['vehicle_type']??'',['motorcycle','car','bicycle','other'],true)?$_POST['vehicle_type']:'motorcycle';$app->exec('UPDATE driver_profiles SET vehicle_type=?,plate=?,identity_number=?,service_area=?,sinpe_phone=? WHERE user_id=?',[$vehicle,trim((string)($_POST['plate']??'')),trim((string)($_POST['identity_number']??'')),trim((string)($_POST['service_area']??'')),trim((string)($_POST['sinpe_phone']??'')),$user['id']]);flash('success','Perfil actualizado.');}
            elseif($action==='request_affiliation'){$slug=slugify((string)($_POST['store_code']??''));$store=$app->one('SELECT * FROM tenants WHERE slug=? AND is_active=1',[$slug]);if(!$store||!module_enabled_v12($app,$store,'drivers'))throw new RuntimeException('No encontramos un negocio con Red de motorizados activa usando ese código.');$app->exec('INSERT INTO driver_affiliations(user_id,tenant_id,status,requested_by,all_branches) VALUES(?,?,"pending_store","driver",1) ON DUPLICATE KEY UPDATE status=IF(status="blocked","blocked","pending_store"),requested_by="driver"',[$user['id'],$store['id']]);flash('success','Solicitud enviada a '.$store['name'].'.');}
            elseif($action==='affiliation_decision'){$affiliationId=(int)($_POST['affiliation_id']??0);$decision=(string)($_POST['decision']??'');if(!in_array($decision,['active','rejected','paused'],true))throw new RuntimeException('Decisión inválida.');$allowed=$decision==='active'?'pending_driver':($decision==='rejected'?'pending_driver':'active');$statement=$app->db->prepare('UPDATE driver_affiliations SET status=? WHERE id=? AND user_id=? AND status=?');$statement->execute([$decision,$affiliationId,$user['id'],$allowed]);if($statement->rowCount()!==1)throw new RuntimeException('La afiliación cambió de estado.');}
            elseif($action==='accept'){$jobId=(int)($_POST['job_id']??0);$app->db->beginTransaction();$app->one('SELECT user_id FROM driver_profiles WHERE user_id=? FOR UPDATE',[$user['id']]);if($app->one('SELECT id FROM delivery_jobs WHERE assigned_driver_id=? AND status IN("assigned","arrived","picked_up","in_transit","issue") LIMIT 1',[$user['id']]))throw new RuntimeException('Finaliza tu entrega activa antes de aceptar otra.');$job=$app->one('SELECT j.id FROM delivery_jobs j JOIN tenants t ON t.id=j.tenant_id AND t.is_active=1 JOIN orders o ON o.id=j.order_id AND o.status NOT IN("cancelled","delivered") JOIN driver_affiliations da ON da.tenant_id=j.tenant_id AND da.user_id=? AND da.status="active" WHERE j.id=? AND j.status="available" AND (da.all_branches=1 OR EXISTS(SELECT 1 FROM driver_affiliation_branches dab WHERE dab.affiliation_id=da.id AND dab.branch_id=j.branch_id)) FOR UPDATE',[$user['id'],$jobId]);if(!$job)throw new RuntimeException('Este express ya no está disponible para tu perfil.');$app->exec('UPDATE delivery_jobs SET assigned_driver_id=?,status="assigned",accepted_at=NOW() WHERE id=? AND status="available"',[$user['id'],$jobId]);$app->db->commit();flash('success','Express aceptado. Ya puedes ver la dirección y contacto del cliente.');}
            elseif(in_array($action,['arrived','picked_up','in_transit','delivered','issue'],true)){$jobId=(int)($_POST['job_id']??0);$reference=$app->one('SELECT order_id,tenant_id FROM delivery_jobs WHERE id=? AND assigned_driver_id=?',[$jobId,$user['id']]);if(!$reference)throw new RuntimeException('Entrega no encontrada.');$app->db->beginTransaction();$order=$app->one('SELECT status FROM orders WHERE id=? AND tenant_id=? FOR UPDATE',[$reference['order_id'],$reference['tenant_id']]);$job=$app->one('SELECT * FROM delivery_jobs WHERE id=? AND assigned_driver_id=? FOR UPDATE',[$jobId,$user['id']]);if(!$job||!$order||in_array($order['status'],['cancelled','delivered'],true))throw new RuntimeException('El pedido ya terminó. Actualiza tu pantalla para continuar.');$map=['arrived'=>['assigned','arrived'],'picked_up'=>['arrived','picked_up'],'in_transit'=>['picked_up','in_transit'],'delivered'=>['in_transit','delivered'],'issue'=>[null,'issue']];[$from,$to]=$map[$action];if($action==='issue'&&!in_array($job['status'],['assigned','arrived','picked_up','in_transit','issue'],true))throw new RuntimeException('Esta entrega ya terminó. No se puede reabrir como incidente.');if($from&&$job['status']!==$from)throw new RuntimeException('El express cambió de estado.');if($action==='issue'&&$job['status']!=='issue')$app->exec('UPDATE delivery_jobs SET issue_previous_status=? WHERE id=?',[$job['status'],$jobId]);if($to==='delivered'){if(!password_verify(trim((string)($_POST['delivery_pin']??'')),(string)$job['delivery_pin_hash']))throw new RuntimeException('El PIN de entrega no es correcto.');}$app->exec('UPDATE delivery_jobs SET status=?,updated_at=NOW()'.($to==='picked_up'?',picked_up_at=NOW()':'').($to==='delivered'?',delivered_at=NOW()':'').' WHERE id=? AND assigned_driver_id=?',[$to,$jobId,$user['id']]);if($to==='delivered'){$app->exec('UPDATE orders SET status="delivered" WHERE id=? AND tenant_id=?',[$job['order_id'],$job['tenant_id']]);$app->exec('UPDATE driver_profiles SET completed_deliveries=completed_deliveries+1 WHERE user_id=?',[$user['id']]);loyalty_sync_order_v12($app,(int)$job['order_id']);}$app->db->commit();}
        }catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e->getMessage());}redirect(url('driver'));
    }
    $profile=$app->one('SELECT * FROM driver_profiles WHERE user_id=?',[$user['id']]);$active=$app->one('SELECT j.*,o.order_number,o.customer_name,o.customer_phone,o.address,o.address_reference,o.payment_method,o.total,o.notes,t.name tenant_name,t.address tenant_address,b.name branch_name,b.address pickup_address,b.phone branch_phone FROM delivery_jobs j JOIN orders o ON o.id=j.order_id JOIN tenants t ON t.id=j.tenant_id LEFT JOIN branches b ON b.id=j.branch_id WHERE j.assigned_driver_id=? AND j.status IN("assigned","arrived","picked_up","in_transit","issue") ORDER BY j.accepted_at LIMIT 1',[$user['id']]);
    $available=[];if($profile['is_online']&&!$active){$available=$app->all('SELECT j.*,o.order_number,o.payment_method,o.total,o.scheduled_at,t.name tenant_name,t.logo tenant_logo,t.address tenant_address,t.plan tenant_plan,b.name branch_name,b.address pickup_address FROM delivery_jobs j JOIN orders o ON o.id=j.order_id JOIN tenants t ON t.id=j.tenant_id AND t.is_active=1 JOIN driver_affiliations da ON da.tenant_id=j.tenant_id AND da.user_id=? AND da.status="active" LEFT JOIN branches b ON b.id=j.branch_id WHERE j.status="available" AND o.status NOT IN("cancelled","delivered") AND (da.all_branches=1 OR EXISTS(SELECT 1 FROM driver_affiliation_branches dab WHERE dab.affiliation_id=da.id AND dab.branch_id=j.branch_id)) ORDER BY j.created_at LIMIT 100',[$user['id']]);$available=array_values(array_filter($available,static fn(array $job):bool=>module_enabled_v12($app,['id'=>$job['tenant_id'],'plan'=>$job['tenant_plan']],'express')&&module_enabled_v12($app,['id'=>$job['tenant_id'],'plan'=>$job['tenant_plan']],'drivers')));}
    $affiliations=$app->all('SELECT da.*,t.name tenant_name,t.slug,t.logo,(SELECT GROUP_CONCAT(b.name ORDER BY b.name SEPARATOR ", ") FROM driver_affiliation_branches dab JOIN branches b ON b.id=dab.branch_id WHERE dab.affiliation_id=da.id) branch_names FROM driver_affiliations da JOIN tenants t ON t.id=da.tenant_id WHERE da.user_id=? ORDER BY FIELD(da.status,"pending_driver","pending_store","active","paused","rejected","blocked"),t.name',[$user['id']]);$today=$app->one('SELECT COUNT(*) deliveries,COALESCE(SUM(payout),0) earnings FROM delivery_jobs WHERE assigned_driver_id=? AND status="delivered" AND DATE(delivered_at)=CURDATE()',[$user['id']]);
    layout_start('FISITAPP Express');echo '<main class="driver-app"><header class="driver-top"><div><small>Red multinegocio</small><h1>Hola, '.e($user['name']).'</h1></div><form method="post" action="'.url('logout').'">'.csrf_field().'<button class="icon-btn" aria-label="Cerrar sesión">↪</button></form></header><section class="driver-stats"><article><small>Entregas hoy</small><strong>'.(int)$today['deliveries'].'</strong></article><article><small>Ganancias hoy</small><strong>'.money((float)$today['earnings']).'</strong></article><article><small>Negocios activos</small><strong>'.count(array_filter($affiliations,fn($row)=>$row['status']==='active')).'</strong></article></section>';render_flashes();echo '<form class="driver-online card" method="post">'.csrf_field().'<input type="hidden" name="action" value="toggle"><div><span class="driver-dot '.($profile['is_online']?'online':'').'"></span><strong>'.($profile['is_online']?'Estás disponible para todos tus afiliados':'No estás disponible').'</strong></div><label class="switch"><input type="checkbox" name="online" '.($profile['is_online']?'checked':'').' onchange="this.form.submit()"><span></span></label></form>';
    if($active){$next=['assigned'=>['Llegué al negocio','arrived'],'arrived'=>['Recogí el pedido','picked_up'],'picked_up'=>['Iniciar ruta','in_transit'],'in_transit'=>['Confirmar entrega','delivered'],'issue'=>['Incidencia reportada','issue']][$active['status']];echo '<section class="card driver-active"><span class="tag">ENTREGA ACTIVA · '.e($active['tenant_name']).'</span><h2>Pedido #'.e($active['order_number']).'</h2><div class="route-stop"><b>A</b><div><small>Recoger en</small><strong>'.e($active['branch_name']??$active['tenant_name']).'</strong><p>'.e($active['pickup_address']??$active['tenant_address']).'</p></div></div><div class="route-line"></div><div class="route-stop"><b>B</b><div><small>Entregar a</small><strong>'.e($active['customer_name']).'</strong><p>'.e($active['address']).'<br>'.e($active['address_reference']).'</p><small>Cobro: '.money((float)$active['total']).' · '.e($active['payment_method']).'</small></div></div>'.($active['notes']?'<div class="ops-notes"><strong>Notas:</strong> '.nl2br(e($active['notes'])).'</div>':'').'<div class="driver-actions"><a class="btn btn-light" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='.rawurlencode((string)$active['address']).'">Abrir mapa</a><a class="btn btn-light" href="tel:'.e(preg_replace('/\D+/','',$active['customer_phone'])).'">Llamar</a><form method="post">'.csrf_field().'<input type="hidden" name="job_id" value="'.(int)$active['id'].'">'.($next[1]==='delivered'?'<input class="input compact" name="delivery_pin" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" placeholder="PIN del cliente" required>':'').($active['status']==='issue'?'<span class="status">Incidencia reportada</span>':'<button class="btn btn-accent" name="action" value="'.e($next[1]).'">'.e($next[0]).'</button>').'</form>'.($active['status']!=='issue'?'<form method="post">'.csrf_field().'<input type="hidden" name="job_id" value="'.(int)$active['id'].'"><button class="btn btn-light" name="action" value="issue">Reportar incidencia</button></form>':'<p class="muted">Contacta al negocio. Debe resolver la incidencia para que puedas continuar la entrega.</p>').'</div></section>';}else{echo '<section><h2>Express disponibles de tus negocios</h2><div class="driver-jobs">';foreach($available as $job)echo '<article class="card driver-job"><div><span class="tag">'.e($job['tenant_name']).'</span><h3>'.e($job['branch_name']??$job['tenant_name']).'</h3><p class="muted">Recoger: '.e($job['pickup_address']??$job['tenant_address']).'<br>Zona de entrega: '.e($job['zone_label']).'<br>Cobro del pedido: '.money((float)$job['total']).' · '.e($job['payment_method']).($job['scheduled_at']?'<br>Programado: '.e(date('d/m H:i',strtotime($job['scheduled_at']))):'').'</p></div><strong class="job-pay">'.money((float)$job['payout']).'</strong><form method="post">'.csrf_field().'<input type="hidden" name="action" value="accept"><input type="hidden" name="job_id" value="'.(int)$job['id'].'"><button class="btn btn-block">Aceptar express</button></form></article>';if(!$available)echo '<div class="card empty">'.($profile['is_online']?'No hay express disponibles entre tus negocios afiliados.':'Actívate para ver entregas disponibles.').'</div>';echo '</div></section>';}
    echo '<section class="card admin-card driver-affiliation-panel"><div class="section-head"><div><span class="tag">AFILIACIONES</span><h2>Mis negocios</h2></div></div><form method="post" class="driver-affiliation-request">'.csrf_field().'<input type="hidden" name="action" value="request_affiliation"><input class="input" name="store_code" placeholder="Código o enlace del negocio, por ejemplo sabor-urbano-demo" required><button class="btn">Solicitar afiliación</button></form><div class="driver-businesses">';foreach($affiliations as $affiliation){$scope=$affiliation['all_branches']?'Todas las sucursales':($affiliation['branch_names']?:'Sin sucursales autorizadas');echo '<article><div>'.($affiliation['logo']?'<img src="'.e(public_media_url($affiliation['logo'])).'" alt="">':'<span class="loyalty-brand-mark">F</span>').'<div><strong>'.e($affiliation['tenant_name']).'</strong><small>'.e($scope).' · '.e($affiliation['status']).'</small></div></div><form method="post">'.csrf_field().'<input type="hidden" name="action" value="affiliation_decision"><input type="hidden" name="affiliation_id" value="'.(int)$affiliation['id'].'">'.($affiliation['status']==='pending_driver'?'<button class="btn btn-accent" name="decision" value="active">Aceptar</button><button class="btn btn-light" name="decision" value="rejected">Rechazar</button>':($affiliation['status']==='active'?'<button class="btn btn-light" name="decision" value="paused">Salir</button>':'')).'</form></article>';}if(!$affiliations)echo '<div class="empty">Aún no estás afiliado a ningún negocio.</div>';echo '</div></section><details class="card admin-card driver-profile"><summary>Editar mi perfil de motorizado</summary><form method="post">'.csrf_field().'<input type="hidden" name="action" value="profile"><div class="split"><div class="form-group"><label>Vehículo</label><select class="input" name="vehicle_type">';foreach(['motorcycle'=>'Motocicleta','car'=>'Automóvil','bicycle'=>'Bicicleta','other'=>'Otro'] as $key=>$label)echo '<option value="'.$key.'" '.($profile['vehicle_type']===$key?'selected':'').'>'.$label.'</option>';echo '</select></div>'.field('Placa','plate',$profile['plate']??'').'</div>'.field('Cédula','identity_number',$profile['identity_number']??'').field('Zona de trabajo','service_area',$profile['service_area']??'').field('Teléfono SINPE','sinpe_phone',$profile['sinpe_phone']??'').'<button class="btn">Guardar perfil</button></form></details></main>';layout_end();
}

function seo_head_v12(App $app,string $title,?array $tenant,bool $admin):string
{
    $path=request_path();$private=$admin||preg_match('~^(?:login|owner-login|register|forgot-password|reset-password|account|admin|master|driver|driver-register|upgrade)(?:/|$)~',$path);$canonical=url($path);$name=$tenant['name']??$app->setting('site_name','FISITAPP');$description=$tenant?'Compra en '.($tenant['name']??'esta tienda').' mediante su catálogo digital FISITAPP.':$app->setting('seo_description','Crea tu tienda en línea, recibe pedidos y administra clientes con FISITAPP.');$image=public_media_url($tenant['logo']??$app->setting('platform_logo',url('assets/fisitapp-logo.webp')));$type=$tenant?'website':'website';$schema=$tenant?['@context'=>'https://schema.org','@type'=>'LocalBusiness','name'=>$name,'url'=>url($tenant['slug']??''),'image'=>$image,'telephone'=>$tenant['phone']??'','address'=>$tenant['address']??'']:['@context'=>'https://schema.org','@type'=>'Organization','name'=>'FISITAPP','url'=>url(),'logo'=>$image];return '<meta name="description" content="'.e($description).'"><meta name="robots" content="'.($private?'noindex,nofollow':'index,follow,max-image-preview:large').'"><link rel="canonical" href="'.e($canonical).'"><meta property="og:locale" content="es_CR"><meta property="og:type" content="'.$type.'"><meta property="og:title" content="'.e($title.' · '.$name).'"><meta property="og:description" content="'.e($description).'"><meta property="og:url" content="'.e($canonical).'"><meta property="og:image" content="'.e($image).'"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">'.json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG).'</script>';
}

function robots_v12():never
{
    header('Content-Type:text/plain; charset=utf-8');header('Cache-Control:public,max-age=3600');echo "User-agent: *\nAllow: /\nDisallow: /admin\nDisallow: /master\nDisallow: /account\nDisallow: /driver\nDisallow: /driver-register\nDisallow: /upgrade\nDisallow: /login\nDisallow: /owner-login\nSitemap: ".url('sitemap.xml')."\n";exit;
}

function sitemap_v12(App $app):never
{
    header('Content-Type:application/xml; charset=utf-8');header('Cache-Control:public,max-age=3600');$urls=[[url(),date('Y-m-d')],[url('blog'),date('Y-m-d')]];foreach($app->all("SELECT slug,catalog_label,updated_at FROM tenants WHERE is_active=1 AND is_listed=1 AND slug NOT IN ('tienda-demo','restaurante-demo') ORDER BY id") as $tenant){$date=substr((string)$tenant['updated_at'],0,10);$urls[]=[url($tenant['slug']),$date];$urls[]=[url($tenant['slug'].'/'.catalog_segment($tenant)),$date];$urls[]=[url($tenant['slug'].'/blog'),$date];$urls[]=[url($tenant['slug'].'/contacto'),$date];}$xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach($urls as [$location,$date])$xml.='<url><loc>'.htmlspecialchars($location,ENT_XML1).'</loc><lastmod>'.e($date).'</lastmod></url>';$xml.='</urlset>';echo $xml;exit;
}
